import { Cart } from "../components/Cart/Cart";
import { Header } from "../components/Header/Header";
import { type CartItem, useCart } from "../shared/cart";

const STARTING_ITEMS: readonly CartItem[] = [
  { id: "tea", name: "Tea", netCents: 450, quantity: 1 },
  { id: "mug", name: "Mug", netCents: 1200, quantity: 2 },
];

export function App() {
  // The cart lives in the root on purpose: docs/architecture/cart.md
  const cart = useCart(STARTING_ITEMS);

  return (
    <>
      <Header />
      <Cart items={cart.items} onAddOne={cart.addOne} />
    </>
  );
}

