import {
  type CartItem,
  formatCents,
  orderTotalCents,
  TAX_RATE_PERCENT,
} from "../../shared/cart";
import { mergeStyleMaps } from "../../shared/styles/mergeStyleMaps";
import own from "./Cart.module.css";
import type { CartClasses } from "./types";

interface CartProps {
  readonly items: readonly CartItem[];
  readonly onAddOne: (id: string) => void;
  readonly classes?: Partial<CartClasses>;
}

export function Cart({ items, onAddOne, classes }: CartProps) {
  const css = mergeStyleMaps<CartClasses>(own, classes);
  return (
    <section className={css.cart} aria-label="Cart">
      <ul>
        {items.map((item) => (
          <li key={item.id} className={css.line}>
            {item.name} × {item.quantity}
            <button
              type="button"
              onClick={() => {
                onAddOne(item.id);
              }}
            >
              One more {item.name}
            </button>
          </li>
        ))}
      </ul>
      <p className={css.total} role="status">
        Total with {TAX_RATE_PERCENT}% tax:{" "}
        {formatCents(orderTotalCents(items))}
      </p>
    </section>
  );
}

