import { z } from "zod";

import type { CartItem } from "./cartItem";

const CART_KEY = "shop-cart";

const StoredCartV1 = z.object({
  version: z.literal(1),
  items: z.array(
    z.object({
      id: z.string(),
      name: z.string(),
      netCents: z.number().int(),
      quantity: z.number().int().positive(),
    }),
  ),
});

const parsed = (text: string): unknown => {
  try {
    return JSON.parse(text);
  } catch (error) {
    if (error instanceof SyntaxError) return null;
    throw error;
  }
};

export const readCart = (): CartItem[] | null => {
  const text = localStorage.getItem(CART_KEY);
  if (text === null) return null;
  const stored = StoredCartV1.safeParse(parsed(text));
  return stored.success ? stored.data.items : null;
};

export const writeCart = (items: readonly CartItem[]): void => {
  localStorage.setItem(CART_KEY, JSON.stringify({ version: 1, items }));
};

