import type { CartItem } from "./cartItem";
import { priceWithTaxCents } from "./price";

export function orderTotalCents(items: readonly CartItem[]): number {
  return items.reduce(
    (sum, item) => sum + priceWithTaxCents(item.netCents) * item.quantity,
    0,
  );
}

