export const TAX_RATE_PERCENT = 20;

const PERCENT_BASE = 100;
const CENTS_PER_UNIT = 100;

export function priceWithTaxCents(netCents: number): number {
  return Math.round(
    (netCents * (PERCENT_BASE + TAX_RATE_PERCENT)) / PERCENT_BASE,
  );
}

export function formatCents(cents: number): string {
  return (cents / CENTS_PER_UNIT).toFixed(2);
}

