import { act, renderHook } from "@testing-library/react";
import { afterEach, describe, expect, it } from "vitest";

import { readCart, writeCart } from "../cartStorage";
import { useCart } from "../useCart";

const ITEMS = [
  { id: "a", name: "A", netCents: 100, quantity: 1 },
  { id: "b", name: "B", netCents: 200, quantity: 3 },
];

describe("useCart", () => {
  afterEach(() => {
    localStorage.clear();
  });

  it("starts with the items it was given", () => {
    const { result } = renderHook(() => useCart(ITEMS));
    expect(result.current.items).toEqual(ITEMS);
  });

  it("adds one to the named item only", () => {
    const { result } = renderHook(() => useCart(ITEMS));
    act(() => {
      result.current.addOne("b");
    });
    expect(result.current.items.map((item) => item.quantity)).toEqual([1, 4]);
  });

  it("starts from the stored cart when there is one", () => {
    writeCart([{ id: "c", name: "C", netCents: 300, quantity: 5 }]);
    const { result } = renderHook(() => useCart(ITEMS));
    expect(result.current.items.map((item) => item.id)).toEqual(["c"]);
  });

  it("stores the items after a change", () => {
    const { result } = renderHook(() => useCart(ITEMS));
    act(() => {
      result.current.addOne("a");
    });
    expect(readCart()?.map((item) => item.quantity)).toEqual([2, 3]);
  });

  it("stops a line at the most the shop sells", () => {
    const full = [{ id: "a", name: "A", netCents: 100, quantity: 99 }];
    const { result } = renderHook(() => useCart(full));
    act(() => {
      result.current.addOne("a");
    });
    expect(result.current.items[0]?.quantity).toBe(99);
  });
});

