import { useEffect, useState } from "react";

import type { CartItem } from "./cartItem";
import { readCart, writeCart } from "./cartStorage";

// CONSTRAINT — the shop sells at most 99 of one product per order.
const MAX_QUANTITY_PER_LINE = 99;

export function useCart(startingItems: readonly CartItem[]) {
  const [items, setItems] = useState<readonly CartItem[]>(
    () => readCart() ?? startingItems,
  );

  useEffect(() => {
    writeCart(items);
  }, [items]);

  function addOne(id: string) {
    setItems((current) =>
      current.map((item) =>
        item.id === id
          ? {
              ...item,
              quantity: Math.min(item.quantity + 1, MAX_QUANTITY_PER_LINE),
            }
          : item,
      ),
    );
  }

  return { items, addOne };
}
